import { IsEnum, IsHexadecimal, IsString, IsUUID, Length } from 'class-validator';
import { AccessLevel } from '../../../common/types';
import { IsAccountPassword, IsEncoded, IsUsername } from '../../../common/validation';
import { KeyMaterialDto } from './key-material.dto';

export class CreateInviteDto {
  /** Generated by the owner's client; the sealed secret is bound to it. */
  @IsUUID('4')
  id: string;

  @IsUsername()
  username: string;

  @IsEnum(AccessLevel)
  accessLevel: AccessLevel;

  /** SHA-256 of the token derived from the link's secret, hex. */
  @IsString()
  @IsHexadecimal()
  @Length(64, 64)
  tokenHash: string;

  @IsEncoded(512)
  ownerSecretEncrypted: string;
}

export class AcceptInviteDto extends KeyMaterialDto {
  @IsEncoded(64)
  token: string;

  @IsAccountPassword()
  password: string;

  /** HMAC over the new user's identity, keyed from the link's secret. */
  @IsEncoded(64)
  keyBinding: string;
}
